<script module lang="ts">
/**
 * A list beside the selected item's detail (`design/archetypes/master-detail-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/master-detail-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import {
  Render,
  afterRender,
  joinSlot,
  masterDetailFocus,
  masterDetailHolds,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/archetypes/master-detail-page.module.css'
import Button from '../controls/Button.svelte'
import EmptyState from '../structure/EmptyState.svelte'
import PageHeader from '../structure/PageHeader.svelte'
import SplitPane from '../layout/SplitPane.svelte'
import type { EmptyStateProps } from '../structure/EmptyState.svelte'

export interface MasterDetailPageProps {
  /**
   * Vocabulary controls with at most one primary.
   */
  actions?: Snippet
  /**
   * The way back to the list while the detail is drawn alone.
   */
  backLabel: string
  description?: string
  /**
   * The selected item's detail. Absent means that nothing is selected.
   */
  detail?: Snippet
  /**
   * The detail pane while nothing is selected, in the split. Required so the page always decides
   * it.
   */
  emptyState: EmptyStateProps
  /**
   * The list pane: a List (or a Table or a Tree) with its FilterBar and its pagination. The
   * application marks the selected item `current`.
   */
  list: Snippet
  /**
   * Names the list pane's region and the split's separator.
   */
  listLabel: string
  /**
   * Called by the way back. The application clears its selection here.
   */
  onBack?: () => void
  title: string
}
</script>

<script lang="ts">
let {
  actions,
  backLabel,
  description,
  detail,
  emptyState,
  list,
  listLabel,
  onBack,
  title,
}: MasterDetailPageProps = $props()
const joined = joinSlot(undefined, () => ({}))
const slots = {
  get actions() {
    return actions
  },
  get detail() {
    return detail
  },
  get list() {
    return list
  },
}
let narrow = $state(false)
let held = $state(false)
let selected = $state(false)
let body = $state<HTMLElement | null>(null)
let root = $state<HTMLElement | null>(null)
const measure = $derived(() => {
  if (root === null) return
  const rem = Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16
  narrow = root.getBoundingClientRect().width < 48 * rem
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    measure()
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [root]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
watchEffect(effect1)
onDestroy(() => release1?.())
const effect2 = () => {
  selected = Boolean(slots.detail)
}
watchEffect(effect2, { watch: () => Boolean(slots.detail) })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const listener = (event: DocumentEventMap['focusin']) => {
    held = masterDetailHolds(body, event)
  }
  document.addEventListener('focusin', listener)
  release3 = () => document.removeEventListener('focusin', listener)
}
watchEffect(effect3)
onDestroy(() => release3?.())
const effect4 = () => {
  afterRender(() => masterDetailFocus(body, held))
}
watchEffect(effect4, {
  watch: () => (narrow ? (selected ? 'detail' : 'list') : selected ? 'split-detail' : 'split'),
  mount: false,
})
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    class={styles.page}
    data-layout={narrow ? 'single' : 'split'}
    data-pane={narrow ? (selected ? 'detail' : 'list') : undefined}
    data-member="master-detail-page"
    >{#snippet actionsOfPageHeader1()}{@render actions?.()}{/snippet
    }<PageHeader {title} {description} actions={slots.actions ? actionsOfPageHeader1 : undefined}
    /><div bind:this={body} class={styles.body}
      >{#if narrow
        }<section
          class={styles.list}
          aria-label={listLabel}
          tabindex="-1"
          hidden={selected}
          data-master-detail-page-part="list"
          >{@render list?.()
        }</section
        >{#if selected
          }<div class={styles.detail} data-master-detail-page-part="detail"
            ><div class={styles.back} data-master-detail-page-part="back"
              ><Button
                variant="ghost"
                tone="neutral"
                size="sm"
                icon="back"
                label={backLabel}
                onClick={() => { onBack?.() }}
            /></div
            ><div class={styles.scroll}>{@render detail?.()}</div
          ></div
        >{/if
      }{:else
        }{#snippet startOfSplitPane2()
          }<section
            class={styles.list}
            aria-label={listLabel}
            tabindex="-1"
            data-master-detail-page-part="list"
            >{@render list?.()
          }</section
        >{/snippet
        }{#snippet endOfSplitPane3()
          }<div class={styles.detail} data-master-detail-page-part="detail"
            >{#if selected
              }<div class={styles.scroll}>{@render detail?.()}</div
            >{:else
              }<div class={styles.empty}
                >{#snippet actionOfEmptyState4()}<Render node={emptyState.action} />{/snippet
                }{#snippet secondaryActionOfEmptyState5()
                  }<Render node={emptyState.secondaryAction}
                />{/snippet
                }<EmptyState
                  icon={emptyState.icon}
                  title={emptyState.title}
                  description={emptyState.description}
                  action={emptyState.action !== undefined ? actionOfEmptyState4 : undefined}
                  secondaryAction={emptyState.secondaryAction !== undefined ? secondaryActionOfEmptyState5 : undefined}
              /></div
            >{/if
          }</div
        >{/snippet
        }<SplitPane
          label={listLabel}
          defaultRatio={0.32}
          startMin={240}
          endMin={420}
          start={startOfSplitPane2}
          end={endOfSplitPane3}
      />{/if
    }</div
  ></div
>{/if
}{@render joined.end?.()}
